#[derive(Clone, Debug, Default, PartialEq)]
pub struct Combat {
    pub owner: Ref<Unit>,
    pub player: bool,
    pub last_attacker: Attacker,
    pub aim_override: Nullable<Vec3>,
    pub max_health: f64,
    pub health: f64,
    pub dead: bool,
    pub death_time: f64,
    pub team: f64,
    pub repair_target: Option<RepairTarget>,
    pub repair_lock: StrId,
    pub blow_apart: bool,
    pub chunks: f64,
    pub zoom_step: f64,
    pub kick: Kick,
    pub scale: StrId,
    pub first_person: bool,
    pub mounted: Option<bool>,
    pub gun_underwater: bool,
    pub defer_muzzles: bool,
    pub pending_muzzles: Vec<PendingShot>,
    pub random: bool,
    pub has_remotes: bool,
    pub weapons: Vec<Weapon>,
    pub selected: [f64; 2],
    pub seen: Vec<Seen>,
    pub origin: Vec3,
    pub target: Vec3,
    pub aim_dir: Vec3,
    pub shot_dir: Vec3,
    pub left: Vec3,
    pub up: Vec3,
    pub pivot: Vec3,
}

impl Combat {
    pub const WORDS: usize = 63;

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 63] = (&mut row[..63]).try_into().unwrap();
        row[0] = self.owner.slot as f64; row[0 + 1] = self.owner.gen as f64;
        row[2] = if self.player { 1.0 } else { 0.0 };
        self.last_attacker.put(&mut row[3..3 + 3], heap);
        match &self.aim_override { Nullable::Value(v) => { row[6] = 0.0; row[6 + 1..6 + 1 + 3].copy_from_slice(&(*v)); } Nullable::Null => { row[6] = 1.0; row[6 + 1..6 + 4].fill(0.0); } Nullable::Undefined => { row[6] = 2.0; row[6 + 1..6 + 4].fill(0.0); } }
        row[10] = self.max_health;
        row[11] = self.health;
        row[12] = if self.dead { 1.0 } else { 0.0 };
        row[13] = self.death_time;
        row[14] = self.team;
        match &self.repair_target { Some(v) => { row[15] = 0.0; (*v).put(&mut row[15 + 1..15 + 1 + 3], heap); } None => { row[15] = 1.0; row[15 + 1..15 + 4].fill(0.0); } }
        row[19] = self.repair_lock.0 as f64;
        row[20] = if self.blow_apart { 1.0 } else { 0.0 };
        row[21] = self.chunks;
        row[22] = self.zoom_step;
        self.kick.put(&mut row[23..], heap);
        row[26] = self.scale.0 as f64;
        row[27] = if self.first_person { 1.0 } else { 0.0 };
        match &self.mounted { Some(v) => { row[28] = 0.0; row[28 + 1] = if (*v) { 1.0 } else { 0.0 }; } None => { row[28] = 2.0; row[28 + 1..28 + 2].fill(0.0); } }
        row[30] = if self.gun_underwater { 1.0 } else { 0.0 };
        row[31] = if self.defer_muzzles { 1.0 } else { 0.0 };
        { let at = heap.len(); row[32] = at as f64; row[32 + 1] = self.pending_muzzles.len() as f64; heap.resize(at + self.pending_muzzles.len() * 15, 0.0); for (i, e) in self.pending_muzzles.iter().enumerate() { let mut item = [0.0f64; 15]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 15..at + (i + 1) * 15].copy_from_slice(&item); } }
        row[34] = if self.random { 1.0 } else { 0.0 };
        row[35] = if self.has_remotes { 1.0 } else { 0.0 };
        { let at = heap.len(); row[36] = at as f64; row[36 + 1] = self.weapons.len() as f64; heap.resize(at + self.weapons.len() * 43, 0.0); for (i, e) in self.weapons.iter().enumerate() { let mut item = [0.0f64; 43]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 43..at + (i + 1) * 43].copy_from_slice(&item); } }
        row[38..38 + 2].copy_from_slice(&self.selected);
        { let at = heap.len(); row[40] = at as f64; row[40 + 1] = self.seen.len() as f64; heap.resize(at + self.seen.len() * 3, 0.0); for (i, e) in self.seen.iter().enumerate() { let mut item = [0.0f64; 3]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 3..at + (i + 1) * 3].copy_from_slice(&item); } }
        row[42..42 + 3].copy_from_slice(&self.origin);
        row[45..45 + 3].copy_from_slice(&self.target);
        row[48..48 + 3].copy_from_slice(&self.aim_dir);
        row[51..51 + 3].copy_from_slice(&self.shot_dir);
        row[54..54 + 3].copy_from_slice(&self.left);
        row[57..57 + 3].copy_from_slice(&self.up);
        row[60..60 + 3].copy_from_slice(&self.pivot);
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 63] = (&row[..63]).try_into().unwrap();
        Self {
            owner: Ref::new(word_u32(row[0]), word_u32(row[0 + 1])),
            player: row[2] != 0.0,
            last_attacker: Attacker::take(&row[3..3 + 3], heap),
            aim_override: match word_u32(row[6]) { 0 => Nullable::Value([row[6 + 1], row[6 + 1 + 1], row[6 + 1 + 2]]), 1 => Nullable::Null, _ => Nullable::Undefined },
            max_health: row[10],
            health: row[11],
            dead: row[12] != 0.0,
            death_time: row[13],
            team: row[14],
            repair_target: if row[15] == 0.0 { Some(RepairTarget::take(&row[15 + 1..15 + 1 + 3], heap)) } else { None },
            repair_lock: StrId(word_u32(row[19])),
            blow_apart: row[20] != 0.0,
            chunks: row[21],
            zoom_step: row[22],
            kick: Kick::take(&row[23..], heap),
            scale: StrId(word_u32(row[26])),
            first_person: row[27] != 0.0,
            mounted: if row[28] == 0.0 { Some(row[28 + 1] != 0.0) } else { None },
            gun_underwater: row[30] != 0.0,
            defer_muzzles: row[31] != 0.0,
            pending_muzzles: { let (at, n) = (word_u32(row[32]) as usize, word_u32(row[32 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 15..at + (i + 1) * 15]; out.push(PendingShot::take(&row[0..], heap)); } out },
            random: row[34] != 0.0,
            has_remotes: row[35] != 0.0,
            weapons: { let (at, n) = (word_u32(row[36]) as usize, word_u32(row[36 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 43..at + (i + 1) * 43]; out.push(Weapon::take(&row[0..], heap)); } out },
            selected: { let mut a = [0.0; 2]; a.copy_from_slice(&row[38..38 + 2]); a },
            seen: { let (at, n) = (word_u32(row[40]) as usize, word_u32(row[40 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 3..at + (i + 1) * 3]; out.push(Seen::take(&row[0..], heap)); } out },
            origin: [row[42], row[42 + 1], row[42 + 2]],
            target: [row[45], row[45 + 1], row[45 + 2]],
            aim_dir: [row[48], row[48 + 1], row[48 + 2]],
            shot_dir: [row[51], row[51 + 1], row[51 + 2]],
            left: [row[54], row[54 + 1], row[54 + 2]],
            up: [row[57], row[57 + 1], row[57 + 2]],
            pivot: [row[60], row[60 + 1], row[60 + 2]],
        }
    }

}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct CbEdge {
    pub button: f64,
    pub id: Option<f64>,
    pub late: Option<f64>,
    pub aim_yaw: Option<f64>,
    pub aim_pitch: Option<f64>,
}

impl CbEdge {
    pub const WORDS: usize = 9;

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 9] = (&mut row[..9]).try_into().unwrap();
        row[0] = self.button;
        match &self.id { Some(v) => { row[1] = 0.0; row[1 + 1] = (*v); } None => { row[1] = 2.0; row[1 + 1..1 + 2].fill(0.0); } }
        match &self.late { Some(v) => { row[3] = 0.0; row[3 + 1] = (*v); } None => { row[3] = 2.0; row[3 + 1..3 + 2].fill(0.0); } }
        match &self.aim_yaw { Some(v) => { row[5] = 0.0; row[5 + 1] = (*v); } None => { row[5] = 2.0; row[5 + 1..5 + 2].fill(0.0); } }
        match &self.aim_pitch { Some(v) => { row[7] = 0.0; row[7 + 1] = (*v); } None => { row[7] = 2.0; row[7 + 1..7 + 2].fill(0.0); } }
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 9] = (&row[..9]).try_into().unwrap();
        Self {
            button: row[0],
            id: if row[1] == 0.0 { Some(row[1 + 1]) } else { None },
            late: if row[3] == 0.0 { Some(row[3 + 1]) } else { None },
            aim_yaw: if row[5] == 0.0 { Some(row[5 + 1]) } else { None },
            aim_pitch: if row[7] == 0.0 { Some(row[7 + 1]) } else { None },
        }
    }

}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct CbShot {
    pub unit: f64,
    pub weapon: f64,
    pub kind: CbShotKind,
    pub yaw: f64,
    pub pitch: f64,
    pub charge: f64,
    pub target_id: f64,
    pub target_generation: f64,
    pub admission: Option<f64>,
    pub swing: f64,
}

impl CbShot {
    pub const WORDS: usize = 11;

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 11] = (&mut row[..11]).try_into().unwrap();
        row[0] = self.unit;
        row[1] = self.weapon;
        row[2] = self.kind as u8 as f64;
        row[3] = self.yaw;
        row[4] = self.pitch;
        row[5] = self.charge;
        row[6] = self.target_id;
        row[7] = self.target_generation;
        match &self.admission { Some(v) => { row[8] = 0.0; row[8 + 1] = (*v); } None => { row[8] = 2.0; row[8 + 1..8 + 2].fill(0.0); } }
        row[10] = self.swing;
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 11] = (&row[..11]).try_into().unwrap();
        Self {
            unit: row[0],
            weapon: row[1],
            kind: CbShotKind::from_u8(word_u32(row[2]) as u8).unwrap_or_default(),
            yaw: row[3],
            pitch: row[4],
            charge: row[5],
            target_id: row[6],
            target_generation: row[7],
            admission: if row[8] == 0.0 { Some(row[8 + 1]) } else { None },
            swing: row[10],
        }
    }

}
